#!/usr/bin/env python3
"""
Scalar Phos — Benchmark Result Parser
Parses lm-evaluation-harness JSON output logs and formats them into Markdown tables.
Licensed under the Apache License 2.0
"""

import json
import os
import sys
import glob


def find_latest_result_file(eval_dir="./eval_results"):
    """Locates the most recent JSON result file generated by lm-eval."""
    if not os.path.exists(eval_dir):
        print(f"Error: Directory '{eval_dir}' not found.")
        sys.exit(1)
    
    json_files = glob.glob(os.path.join(eval_dir, "**", "*.json"), recursive=True)
    if not json_files:
        print(f"Error: No JSON result files found in '{eval_dir}'.")
        sys.exit(1)
        
    latest_file = max(json_files, key=os.path.getmtime)
    return latest_file


def parse_results(filepath):
    print(f"Parsing evaluation log: {filepath}\n")
    try:
        with open(filepath, "r") as f:
            data = json.load(f)
    except Exception as e:
        print(f"Failed to read JSON file: {e}")
        sys.exit(1)

    results = data.get("results", {})
    config = data.get("config", {})
    model_name = config.get("model_args", "Unknown Model")

    print("### Evaluation Results Report\n")
    print(f"- **Target Configuration:** `{model_name}`")
    print(f"- **Timestamp:** {data.get('date', 'N/A')}\n")

    print("| Benchmark / Metric Category | Score |")
    print("| :--- | :---: |")

    for task, metrics in results.items():
        score = metrics.get("exact_match,none", metrics.get("acc,none", metrics.get("acc_norm,none", None)))
        if score is not None:
            formatted_score = f"{score * 100:.2f}%" if score <= 1.0 else f"{score:.2f}%"
            print(f"| **{task}** | **{formatted_score}** |")

    print("\n*Parsed successfully via Scalar Phos evaluation suite.*")


if __name__ == "__main__":
    target_file = sys.argv[1] if len(sys.argv) > 1 else find_latest_result_file()
    parse_results(target_file)
